package authz

import (
	"slices"
	"sort"
	"strings"
	"time"

	"github.com/luwa07832/rbac-admin-api/internal/store"
)

// Access sources reported by the effective-access listing.
const (
	SourceRole             = "ROLE"
	SourceDirectPermission = "DIRECT_PERMISSION"
)

// AccessInput is the effective-access query: one subject at one moment.
type AccessInput struct {
	Subject     string
	EffectiveAt string
}

// AccessItem is one effective authorization path in public shape. Role-derived
// items keep the directly bound role alongside the inherited role carrying the
// permission; direct permission grants skip the role layer and leave both role
// fields null.
type AccessItem struct {
	Source     string   `json:"source"`
	BoundRole  *string  `json:"boundRole"`
	Role       *string  `json:"role"`
	Permission string   `json:"permission"`
	Operations []string `json:"operations"`
	Scope      string   `json:"scope"`
}

// Access lists the subject's authorization paths whose three interval layers
// all contain effectiveAt (defaulting to now). The query is read-only and an
// empty result is a normal outcome, never an error. A malformed effectiveAt
// is the one failure that outranks subject validation.
func (s *Service) Access(in AccessInput) ([]AccessItem, *Failure) {
	at := time.Now().UTC()
	if in.EffectiveAt != "" {
		parsed, fail := ParseTime(in.EffectiveAt)
		if fail != nil {
			return nil, fail
		}
		at = parsed
	}
	if !validIdentifier(in.Subject) {
		return nil, invalidRequest("subject", "field subject is not a parseable identifier")
	}
	if exists, err := s.store.Exists(store.CatalogSubject, in.Subject); err != nil || !exists {
		return nil, notFoundOrInternal("subject", err, !exists)
	}
	snap, err := s.loadSnapshot(in.Subject)
	if err != nil {
		return nil, failure(TypeInvalidRequest, "", "could not evaluate access")
	}
	return listAccess(snap, FormatTime(at)), nil
}

// listAccess flattens every authorization path active at the given instant:
// role-derived paths join an active binding, the inherited role's active
// permission grant and an active scope on that same role, while direct
// permission grants stand on their own. Overlapping interval versions of one
// identity collapse into a single item, and the result is ordered by the
// published field sequence.
func listAccess(snap *snapshot, at string) []AccessItem {
	boundRoles := map[string]bool{}
	for _, row := range snap.bindings {
		if rowActive(row.effectiveFrom, row.effectiveTo, at) {
			boundRoles[row.roleID] = true
		}
	}
	reachableCache := map[string]map[string]bool{}
	reachableFrom := func(role string) map[string]bool {
		reachable, ok := reachableCache[role]
		if !ok {
			reachable = reachableRoles(map[string]bool{role: true}, snap.roleParents)
			reachableCache[role] = reachable
		}
		return reachable
	}
	activePairs := map[[2]string]bool{}
	for _, row := range snap.rolePerm {
		if rowActive(row.effectiveFrom, row.effectiveTo, at) {
			activePairs[[2]string{row.roleID, row.permissionID}] = true
		}
	}

	items := []AccessItem{}
	seen := map[string]bool{}
	add := func(source, boundRole, role, permission, scope string) {
		operations := sortedOperations(snap.permOperations[permission])
		key := accessKey(source, boundRole, role, permission, operations, scope)
		if seen[key] {
			return
		}
		seen[key] = true
		items = append(items, AccessItem{
			Source:     source,
			BoundRole:  nullable(boundRole),
			Role:       nullable(role),
			Permission: permission,
			Operations: operations,
			Scope:      scope,
		})
	}

	for _, row := range snap.scopes {
		if !rowActive(row.effectiveFrom, row.effectiveTo, at) {
			continue
		}
		if row.permissionID != "" {
			add(SourceDirectPermission, "", "", row.permissionID, row.scope.text)
			continue
		}
		for pair := range activePairs {
			if pair[0] != row.roleID {
				continue
			}
			for boundRole := range boundRoles {
				if reachableFrom(boundRole)[row.roleID] {
					add(SourceRole, boundRole, row.roleID, pair[1], row.scope.text)
				}
			}
		}
	}

	sort.SliceStable(items, func(i, j int) bool { return accessLess(items[i], items[j]) })
	return items
}

// AccessDiffInput compares one subject's effective paths at two moments.
type AccessDiffInput struct {
	Subject string
	From    string
	To      string
}

// AccessDiffView holds the symmetric difference of the paths effective at
// the two moments; from and to carry the canonical UTC texts.
type AccessDiffView struct {
	From      string       `json:"from"`
	To        string       `json:"to"`
	Added     []AccessItem `json:"added"`
	Removed   []AccessItem `json:"removed"`
	Unchanged []AccessItem `json:"unchanged"`
}

// AccessDiff lists which of the subject's effective authorization paths were
// added, removed or kept between two moments. Both moments are mandatory and
// the query is read-only. Timing validation outranks subject validation, with
// from reported before to; equal moments are a normal request.
func (s *Service) AccessDiff(in AccessDiffInput) (*AccessDiffView, *Failure) {
	if in.From == "" {
		return nil, invalidRequest("from", "from query parameter is required")
	}
	if in.To == "" {
		return nil, invalidRequest("to", "to query parameter is required")
	}
	fromTime, fail := ParseTime(in.From)
	if fail != nil {
		fail.Field = "from"
		return nil, fail
	}
	toTime, fail := ParseTime(in.To)
	if fail != nil {
		fail.Field = "to"
		return nil, fail
	}
	if fromTime.After(toTime) {
		return nil, failure(TypeInvalidRange, "", "the range start must not be later than the range end")
	}
	if !validIdentifier(in.Subject) {
		return nil, invalidRequest("subject", "field subject is not a parseable identifier")
	}
	if exists, err := s.store.Exists(store.CatalogSubject, in.Subject); err != nil || !exists {
		return nil, notFoundOrInternal("subject", err, !exists)
	}

	snap, err := s.loadSnapshot(in.Subject)
	if err != nil {
		return nil, failure(TypeInvalidRequest, "", "could not evaluate access diff")
	}
	fromItems := listAccess(snap, FormatTime(fromTime))
	toItems := listAccess(snap, FormatTime(toTime))

	fromKeys := map[string]bool{}
	for _, item := range fromItems {
		fromKeys[itemKey(item)] = true
	}
	toKeys := map[string]bool{}
	for _, item := range toItems {
		toKeys[itemKey(item)] = true
	}

	view := &AccessDiffView{
		From:      FormatTime(fromTime),
		To:        FormatTime(toTime),
		Added:     []AccessItem{},
		Removed:   []AccessItem{},
		Unchanged: []AccessItem{},
	}
	// listAccess already deduplicates and orders both lists, so membership
	// filtering preserves the published ordering.
	for _, item := range toItems {
		if fromKeys[itemKey(item)] {
			view.Unchanged = append(view.Unchanged, item)
		} else {
			view.Added = append(view.Added, item)
		}
	}
	for _, item := range fromItems {
		if !toKeys[itemKey(item)] {
			view.Removed = append(view.Removed, item)
		}
	}
	return view, nil
}

// itemKey renders one effective path's full field combination for identity.
func itemKey(item AccessItem) string {
	return accessKey(item.Source, pointerText(item.BoundRole), pointerText(item.Role),
		item.Permission, item.Operations, item.Scope)
}

// accessKey joins the complete path combination with a field separator that no
// identifier or operation text can contain.
func accessKey(source, boundRole, role, permission string, operations []string, scope string) string {
	return strings.Join([]string{source, boundRole, role, permission, scope, strings.Join(operations, "\x00")}, "\x00")
}

// sortedOperations renders the permission's static operation set as a
// deduplicated list ordered by identifier.
func sortedOperations(operationSet map[string]bool) []string {
	operations := []string{}
	for operation := range operationSet {
		operations = append(operations, operation)
	}
	sort.Strings(operations)
	return operations
}

// accessLess orders items by source, boundRole, role, permission, operations
// and scope; absent role fields sort as empty text.
func accessLess(a, b AccessItem) bool {
	if a.Source != b.Source {
		return a.Source < b.Source
	}
	if pointerText(a.BoundRole) != pointerText(b.BoundRole) {
		return pointerText(a.BoundRole) < pointerText(b.BoundRole)
	}
	if pointerText(a.Role) != pointerText(b.Role) {
		return pointerText(a.Role) < pointerText(b.Role)
	}
	if a.Permission != b.Permission {
		return a.Permission < b.Permission
	}
	if cmp := slices.Compare(a.Operations, b.Operations); cmp != 0 {
		return cmp < 0
	}
	return a.Scope < b.Scope
}

func pointerText(value *string) string {
	if value == nil {
		return ""
	}
	return *value
}

--- decision ---
package authz

import (
	"sort"
	"time"
)

// Denial reasons returned when granted is false.
const (
	ReasonNoRoleBinding       = "NO_ROLE_BINDING"
	ReasonNoPermissionBinding = "NO_PERMISSION_BINDING"
	ReasonOutOfScope          = "OUT_OF_SCOPE"
	ReasonNotEffective        = "NOT_EFFECTIVE"
)

// DecisionInput is the public authorize payload.
type DecisionInput struct {
	Subject     string `json:"subject"`
	Resource    string `json:"resource"`
	Operation   string `json:"operation"`
	EffectiveAt string `json:"effectiveAt,omitempty"`
}

// Match identifies the role-derived or direct authorization that explains a
// granted decision. Role is empty for direct permission grants.
type Match struct {
	Role       string
	Permission string
	Scope      string
}

// Decision is the service-level conclusion.
type Decision struct {
	Granted bool   `json:"-"`
	Reason  string `json:"-"`
	Match   *Match `json:"-"`
}

// Decide evaluates the triple at effectiveAt, defaulting to the current time.
func (s *Service) Decide(in DecisionInput) (*Decision, *Failure) {
	if fail := requireIdentifiers(in.Subject, in.Resource, in.Operation); fail != nil {
		return nil, fail
	}
	if fail := s.checkTriple(in.Subject, in.Resource, in.Operation); fail != nil {
		return nil, fail
	}
	at := time.Now().UTC()
	if in.EffectiveAt != "" {
		parsed, fail := ParseTime(in.EffectiveAt)
		if fail != nil {
			return nil, fail
		}
		at = parsed
	}

	snap, err := s.loadSnapshot(in.Subject)
	if err != nil {
		return nil, failure(TypeInvalidRequest, "", "could not evaluate authorization")
	}
	return evaluate(snap, in.Resource, in.Operation, at), nil
}

// candidate is one authorization path that structurally covers the triple.
type candidate struct {
	role       string
	permission string
	scope      scopeRef
	from       string
	to         string
}

func candidateLess(a, b candidate) bool {
	if cmp := compareScope(a.scope, b.scope); cmp != 0 {
		return cmp < 0
	}
	if a.permission != b.permission {
		return a.permission < b.permission
	}
	return a.role < b.role
}

// reachableRoles expands statically inherited roles from the entry set.
func reachableRoles(entries map[string]bool, parents map[string][]string) map[string]bool {
	reachable := map[string]bool{}
	queue := make([]string, 0, len(entries))
	for role := range entries {
		reachable[role] = true
		queue = append(queue, role)
	}
	for len(queue) > 0 {
		current := queue[0]
		queue = queue[1:]
		for _, parent := range parents[current] {
			if !reachable[parent] {
				reachable[parent] = true
				queue = append(queue, parent)
			}
		}
	}
	return reachable
}

func activeRoles(snap *snapshot, at string) map[string]bool {
	entries := map[string]bool{}
	for _, row := range snap.bindings {
		if rowActive(row.effectiveFrom, row.effectiveTo, at) {
			entries[row.roleID] = true
		}
	}
	return reachableRoles(entries, snap.roleParents)
}

func rolesEver(snap *snapshot) map[string]bool {
	entries := map[string]bool{}
	for _, row := range snap.bindings {
		entries[row.roleID] = true
	}
	return reachableRoles(entries, snap.roleParents)
}

func rolePermsActive(snap *snapshot, at string) map[[2]string]bool {
	result := map[[2]string]bool{}
	for _, row := range snap.rolePerm {
		if rowActive(row.effectiveFrom, row.effectiveTo, at) {
			result[[2]string{row.roleID, row.permissionID}] = true
		}
	}
	return result
}

func rolePermsEver(snap *snapshot) map[[2]string]bool {
	result := map[[2]string]bool{}
	for _, row := range snap.rolePerm {
		result[[2]string{row.roleID, row.permissionID}] = true
	}
	return result
}

func permissionCovers(snap *snapshot, permissionID, operation string) bool {
	return snap.permOperations[permissionID][operation]
}

// directCandidates returns scope rows that are direct permission grants,
// cover the operation and match the resource pattern. activeOnly filters by
// the given time.
func directCandidates(snap *snapshot, resource, operation, at string, activeOnly bool) []candidate {
	var result []candidate
	for _, row := range snap.scopes {
		if row.permissionID == "" {
			continue
		}
		if !permissionCovers(snap, row.permissionID, operation) || !row.scope.matches(resource) {
			continue
		}
		if activeOnly && !rowActive(row.effectiveFrom, row.effectiveTo, at) {
			continue
		}
		result = append(result, candidate{
			permission: row.permissionID,
			scope:      row.scope,
			from:       row.effectiveFrom,
			to:         row.effectiveTo,
		})
	}
	return result
}

// roleCandidates returns role-derived scope rows reachable through the given
// role set and covering role/permission pairs active at the layer time.
func roleCandidates(snap *snapshot, roles map[string]bool, rolePerms map[[2]string]bool,
	resource, operation, at string, activeOnly bool) []candidate {

	var result []candidate
	for _, row := range snap.scopes {
		if row.permissionID != "" || !roles[row.roleID] || !row.scope.matches(resource) {
			continue
		}
		for pair := range rolePerms {
			if pair[0] != row.roleID || !permissionCovers(snap, pair[1], operation) {
				continue
			}
			if activeOnly && !rowActive(row.effectiveFrom, row.effectiveTo, at) {
				continue
			}
			result = append(result, candidate{
				role:       row.roleID,
				permission: pair[1],
				scope:      row.scope,
				from:       row.effectiveFrom,
				to:         row.effectiveTo,
			})
		}
	}
	return result
}

// evaluate applies the published precedence:
//
//  1. a chain active now (binding, permission, scope interval all contain t)
//     with a scope pattern covering the resource grants;
//  2. otherwise the first layer that structurally existed at some point but is
//     not active now yields NOT_EFFECTIVE;
//  3. a layer that never existed yields its structural reason, with direct
//     permission grants bypassing the role layers.
func evaluate(snap *snapshot, resource, operation string, at time.Time) *Decision {
	atText := FormatTime(at)

	rolesNow := activeRoles(snap, atText)
	rolesPast := rolesEver(snap)
	rolePermsNow := rolePermsActive(snap, atText)
	rolePermsAll := rolePermsEver(snap)

	directNow := directCandidates(snap, resource, operation, atText, true)
	directEver := directCandidates(snap, resource, operation, atText, false)
	roleNowCandidates := roleCandidates(snap, rolesNow, rolePermsNow, resource, operation, atText, true)

	if len(directNow) > 0 {
		return best(directNow)
	}
	if len(roleNowCandidates) > 0 {
		return best(roleNowCandidates)
	}

	// Layer 1 (role-derived path only).
	if len(rolesNow) == 0 && len(rolesPast) > 0 {
		return denied(ReasonNotEffective)
	}

	// Layer 2. A role-derived permission covering the operation is a pair
	// active at the layer time; direct grants live entirely on this layer.
	roleCoversNow := hasCoveringPair(snap, rolesNow, rolePermsNow, operation)
	roleCoversEver := hasCoveringPair(snap, rolesPast, rolePermsAll, operation)

	if !roleCoversNow && (len(directEver) > 0 || roleCoversEver) {
		return denied(ReasonNotEffective)
	}

	// Layer 3. Consider scope rows for paths whose first two layers are
	// active now; an interval that exists but is not active now beats the
	// pattern-mismatch outcome.
	scopeRowsForActivePaths := roleCandidates(snap, rolesNow, rolePermsNow, resource, operation, atText, false)
	if len(directEver) > 0 {
		scopeRowsForActivePaths = append(scopeRowsForActivePaths, directEver...)
	}
	if len(scopeRowsForActivePaths) > 0 {
		return denied(ReasonNotEffective)
	}

	// Structural denials at the first missing layer.
	if len(rolesNow) == 0 {
		return denied(ReasonNoRoleBinding)
	}
	if !roleCoversNow {
		return denied(ReasonNoPermissionBinding)
	}
	return denied(ReasonOutOfScope)
}

func hasCoveringPair(snap *snapshot, roles map[string]bool, rolePerms map[[2]string]bool, operation string) bool {
	for pair := range rolePerms {
		if roles[pair[0]] && permissionCovers(snap, pair[1], operation) {
			return true
		}
	}
	return false
}

func best(candidates []candidate) *Decision {
	sort.SliceStable(candidates, func(i, j int) bool { return candidateLess(candidates[i], candidates[j]) })
	chosen := candidates[0]
	return &Decision{
		Granted: true,
		Match: &Match{
			Role:       chosen.role,
			Permission: chosen.permission,
			Scope:      chosen.scope.text,
		},
	}
}

func denied(reason string) *Decision {
	return &Decision{Granted: false, Reason: reason}
}

--- validation ---
package authz

import "github.com/luwa07832/rbac-admin-api/internal/store"

func invalidRequest(field, message string) *Failure {
	return failure(TypeInvalidRequest, field, message)
}

// requireIdentifiers validates the subject/resource/operation triple grammar.
func requireIdentifiers(subject, resource, operation string) *Failure {
	if !validIdentifier(subject) {
		return invalidRequest("subject", "field subject is not a parseable identifier")
	}
	if !validIdentifier(resource) {
		return invalidRequest("resource", "field resource is not a parseable identifier")
	}
	if !validIdentifier(operation) {
		return invalidRequest("operation", "field operation is not a parseable identifier")
	}
	return nil
}

// checkTriple reports the first unknown member of the triple in the published
// order subject, resource, operation.
func (s *Service) checkTriple(subject, resource, operation string) *Failure {
	for _, check := range []struct {
		kind  store.CatalogKind
		id    string
		field string
	}{
		{store.CatalogSubject, subject, "subject"},
		{store.CatalogResource, resource, "resource"},
		{store.CatalogOperation, operation, "operation"},
	} {
		exists, err := s.store.Exists(check.kind, check.id)
		if err != nil {
			return failure(TypeInvalidRequest, check.field, "could not verify "+check.field)
		}
		if !exists {
			return failure(TypeNotFound, check.field, check.field+" does not exist")
		}
	}
	return nil
}

