 17	// DecisionInput is the public authorize payload.
 18	type DecisionInput struct {
 19		Subject     string `json:"subject"`
 20		Resource    string `json:"resource"`
 21		Operation   string `json:"operation"`
 22		EffectiveAt string `json:"effectiveAt,omitempty"`
 23	}
 24	
 25	// BatchDecisionInput is the payload for one batch authorization request.
 26	// Every query shares EffectiveAt and is evaluated independently in order.
 27	type BatchDecisionInput struct {
 28		EffectiveAt string
 29		Queries     []BatchDecisionQuery
 30	}
 31	
 32	// BatchDecisionQuery identifies one subject/resource/operation triple.
 33	type BatchDecisionQuery struct {
 34		Subject   string
 35		Resource  string
 36		Operation string
 37	}
 38	
 39	// BatchDecision pairs one input query with its authorization decision.
 40	type BatchDecision struct {
 41		Query    BatchDecisionQuery
 42		Decision *Decision
 43	}
 44	
 45	// Match identifies the role-derived or direct authorization that explains a
 46	// granted decision. Role is empty for direct permission grants.
 47	type Match struct {
 48		Role       string
 49		Permission string
 50		Scope      string
 51	}
 52	
 53	// Decision is the service-level conclusion.
 54	type Decision struct {
 55		Granted bool   `json:"-"`
 56		Reason  string `json:"-"`
 57		Match   *Match `json:"-"`
 58	}
 59	
 60	// Decide evaluates the triple at effectiveAt, defaulting to the current time.
 61	func (s *Service) Decide(in DecisionInput) (*Decision, *Failure) {
 62		if fail := requireIdentifiers(in.Subject, in.Resource, in.Operation); fail != nil {
 63			return nil, fail
 64		}
 65		if fail := s.checkTriple(in.Subject, in.Resource, in.Operation); fail != nil {
 66			return nil, fail
 67		}
 68		at := time.Now().UTC()
 69		if in.EffectiveAt != "" {
 70			parsed, fail := ParseTime(in.EffectiveAt)
 71			if fail != nil {
 72				return nil, fail
 73			}
 74			at = parsed
 75		}
 76	
 77		snap, err := s.loadSnapshot(in.Subject)
 78		if err != nil {
 79			return nil, failure(TypeInvalidRequest, "", "could not evaluate authorization")
 80		}
 81		return evaluate(snap, in.Resource, in.Operation, at), nil
 82	}
 83	
 84	// DecideBatch validates the complete batch before evaluating any query. The
 85	// shared effective moment is parsed once, then each query is checked and
 86	// evaluated in request order; duplicate queries are preserved.
 87	func (s *Service) DecideBatch(in BatchDecisionInput) ([]BatchDecision, *Failure) {
 88		at := time.Now().UTC()
 89		if in.EffectiveAt != "" {
 90			parsed, fail := ParseTime(in.EffectiveAt)
 91			if fail != nil {
 92				return nil, fail
 93			}
 94			at = parsed
 95		}
 96		if len(in.Queries) == 0 || len(in.Queries) > 100 {
 97			return nil, invalidRequest("queries", "queries must contain between 1 and 100 items")
 98		}
 99	
100		snapshots := map[string]*snapshot{}
101		decisions := make([]BatchDecision, 0, len(in.Queries))
102		for index, query := range in.Queries {
103			prefix := batchFieldPrefix(index)
104			if fail := requirePrefixedIdentifiers(query.Subject, query.Resource, query.Operation, prefix); fail != nil {
105				return nil, fail
106			}
107			if fail := s.checkTripleWithFieldPrefix(query.Subject, query.Resource, query.Operation, prefix); fail != nil {
108				return nil, fail
109			}
110	
111			snap, ok := snapshots[query.Subject]
112			if !ok {
113				loaded, err := s.loadSnapshot(query.Subject)
114				if err != nil {
115					return nil, failure(TypeInvalidRequest, "", "could not evaluate authorization")
116				}
117				snap = loaded
118				snapshots[query.Subject] = snap
119			}
120			decisions = append(decisions, BatchDecision{
121				Query:    query,
122				Decision: evaluate(snap, query.Resource, query.Operation, at),
123			})
124		}
125		return decisions, nil
126	}
