   103			prefix := batchFieldPrefix(index)
   104			if fail := requirePrefixedIdentifiers(query.Subject, query.Resource, query.Operation, prefix); fail != nil {
   105				return nil, fail
   106			}
   107			if fail := s.checkTripleWithFieldPrefix(query.Subject, query.Resource, query.Operation, prefix); fail != nil {
   108				return nil, fail
   109			}
   110	
   111			snap, ok := snapshots[query.Subject]
   112			if !ok {
   113				loaded, err := s.loadSnapshot(query.Subject)
   114				if err != nil {
   115					return nil, failure(TypeInvalidRequest, "", "could not evaluate authorization")
   116				}
   117				snap = loaded
   118				snapshots[query.Subject] = snap
   119			}
   120			decisions = append(decisions, BatchDecision{
   121				Query:    query,
   122				Decision: evaluate(snap, query.Resource, query.Operation, at),
   123			})
   124		}
   125		return decisions, nil
   126	}
   127	
   128	func batchFieldPrefix(index int) string {
   129		return "queries[" + strconv.Itoa(index) + "]."
   130	}
   131	
   132	// candidate is one authorization path that structurally covers the triple.
   133	type candidate struct {
   134		role       string
   135		permission string
   136		scope      scopeRef
   137		from       string
   138		to         string
   139	}
