 17	// readJSON reads a JSON object body with strict unknown-field and type
 18	// checking. An empty body is allowed when optional is true (timing-only writes
 19	// default every field to its zero value).
 20	func readJSON(c *gin.Context, target any, optional bool) *authz.Failure {
 21		c.Request.Body = http.MaxBytesReader(c.Writer, c.Request.Body, 1<<20)
 22		raw, err := io.ReadAll(c.Request.Body)
 23		if err != nil {
 24			return &authz.Failure{Type: authz.TypeInvalidRequest, Message: "request body is missing or too large"}
 25		}
 26		trimmed := strings.TrimSpace(string(raw))
 27		if trimmed == "" {
 28			if optional {
 29				return nil
 30			}
 31			return &authz.Failure{Type: authz.TypeInvalidRequest, Message: "request body is empty"}
 32		}
 33		decoder := json.NewDecoder(bytes.NewReader(raw))
 34		decoder.DisallowUnknownFields()
 35		if err := decoder.Decode(target); err != nil {
 36			if _, ok := err.(*json.UnmarshalTypeError); ok {
 37				return &authz.Failure{Type: authz.TypeInvalidRequest, Message: fmt.Sprintf("request body field has the wrong type: %v", err)}
 38			}
 39			return &authz.Failure{Type: authz.TypeInvalidRequest, Message: "request body is not valid JSON for this entry"}
 40		}
 41		if decoder.More() {
 42			return &authz.Failure{Type: authz.TypeInvalidRequest, Message: "request body contains more than one JSON value"}
 43		}
 44		return nil
 45	}
