 47	func readStrictJSONObject(c *gin.Context, target any) *authz.Failure {
 48		c.Request.Body = http.MaxBytesReader(c.Writer, c.Request.Body, 1<<20)
 49		raw, err := io.ReadAll(c.Request.Body)
 50		if err != nil {
 51			return &authz.Failure{Type: authz.TypeInvalidRequest, Message: "request body is missing or too large"}
 52		}
 53		if strings.TrimSpace(string(raw)) == "" {
 54			return &authz.Failure{Type: authz.TypeInvalidRequest, Message: "request body is empty"}
 55		}
 56		if fail := decodeStrictJSON(raw, target, ""); fail != nil {
 57			return fail
 58		}
 59		return nil
 60	}
 61	
 62	func decodeStrictJSON(raw []byte, target any, prefix string) *authz.Failure {
 63		decoder := json.NewDecoder(bytes.NewReader(raw))
 64		decoder.DisallowUnknownFields()
 65		if err := decoder.Decode(target); err != nil {
 66			if field, ok := unknownJSONField(err); ok {
 67				return &authz.Failure{
 68					Type:    authz.TypeInvalidRequest,
 69					Field:   prefix + field,
 70					Message: "request body contains an unknown field",
 71				}
 72			}
 73			if field, ok := jsonField(err); ok {
 74				return &authz.Failure{
 75					Type:    authz.TypeInvalidRequest,
 76					Field:   prefix + field,
 77					Message: fmt.Sprintf("request body field has the wrong type: %v", err),
 78				}
 79			}
 80			return &authz.Failure{
 81				Type:    authz.TypeInvalidRequest,
 82				Field:   strings.TrimSuffix(prefix, "."),
 83				Message: fmt.Sprintf("request body has the wrong shape: %v", err),
 84			}
 85		}
 86		if decoder.More() {
 87			return &authz.Failure{
 88				Type:    authz.TypeInvalidRequest,
 89				Field:   strings.TrimSuffix(prefix, "."),
 90				Message: "request body contains more than one JSON value",
 91			}
 92		}
 93		return nil
 94	}
 95	
 96	func unknownJSONField(err error) (string, bool) {
 97		const marker = "json: unknown field \""
 98		message := err.Error()
 99		start := strings.Index(message, marker)
100		if start < 0 {
101			return "", false
102		}
103		start += len(marker)
104		end := strings.Index(message[start:], "\"")
105		if end < 0 {
106			return "", false
107		}
108		return message[start : start+end], true
109	}
110	
111	func jsonField(err error) (string, bool) {
112		var typeError *json.UnmarshalTypeError
113		if !errors.As(err, &typeError) || typeError.Field == "" {
114			return "", false
115		}

