115	层级判定遵循「先看当前是否全链路有效；否则按归属→权限点→范围顺序，第一层历史存在但
116	当前失效的关系产出 `NOT_EFFECTIVE`，从未存在才产出对应结构性原因」；直接权限点授权跳过
117	角色层。同一时刻命中多条时，范围更具体者优先（精确 > 更长前缀 > 前缀 > `*`），再按权限点、
118	角色标识字典序决胜。
119	
120	## `POST /authorize/batch`
121	
122	在同一个可选时刻批量判定 1 到 100 个「主体 / 资源 / 操作」三元组。请求体只接受
123	`effectiveAt` 与 `queries`；省略 `effectiveAt` 时整批共用服务当前时刻，否则共用同一个
124	RFC3339 时刻。每个查询只含 `subject`、`resource`、`operation`，重复三元组不去重，结果严格
125	按输入顺序返回。
126	
127	```json
128	{"effectiveAt":"2026-02-01T00:00:00Z",
129	 "queries":[
130	  {"subject":"user-1","resource":"tenant-a/doc-1","operation":"read"},
131	  {"subject":"user-1","resource":"tenant-b/doc-2","operation":"read"}]}
132	```
133	
134	成功时：
135	
136	```json
137	{"decisions":[
138	  {"subject":"user-1","resource":"tenant-a/doc-1","operation":"read",
139	   "granted":true,"matchedRole":"viewer","matchedPermission":"doc-read","matchedScope":"tenant-a/*"},
140	  {"subject":"user-1","resource":"tenant-b/doc-2","operation":"read",
141	   "granted":false,"reason":"OUT_OF_SCOPE"}]}
142	```
143	
144	每个 `decision` 的获权与拒绝字段、`matchedRole: null` 语义、角色继承、权限点覆盖、范围匹配
145	和半开区间均与同一时刻的 `POST /authorize` 完全一致；拒绝原因仍为 `NO_ROLE_BINDING`、
146	`NO_PERMISSION_BINDING`、`OUT_OF_SCOPE`、`NOT_EFFECTIVE`。没有任何查询获权时仍返回 200。
147	
148	请求先校验顶层结构与 `effectiveAt`，再按下标依次校验并注册检查每个三元组；任一异常只返回
149	单个 `error` 对象，不返回部分 `decisions`。`queries` 缺失、为空、超过 100 项、不是数组、
150	单项缺失字段、含多余字段或标识符非法均返回 `INVALID_REQUEST`；`effectiveAt` 非法返回
151	`INVALID_TIME`，且优先于所有单项检查。错误 `field` 使用 `queries`、`effectiveAt`、
152	`queries[0].subject` 等定位值；合法但未注册成员按 `subject`、`resource`、`operation`
153	顺序返回 `NOT_FOUND`。
154	
155	## `POST /authorize/explain`
156	
157	只读解释一次授权判定：请求体沿用 `POST /authorize` 的 `subject`、`resource`、`operation`
158	与可选 `effectiveAt`，返回判定结论之外还列出该时刻完整覆盖资源与操作的全部授权路径。
  1	package authz
  2	
  3	import "github.com/luwa07832/rbac-admin-api/internal/store"
  4	
  5	func invalidRequest(field, message string) *Failure {
  6		return failure(TypeInvalidRequest, field, message)
  7	}
  8	
  9	// requireIdentifiers validates the subject/resource/operation triple grammar.
 10	func requireIdentifiers(subject, resource, operation string) *Failure {
 11		return requirePrefixedIdentifiers(subject, resource, operation, "")
 12	}
 13	
 14	func requirePrefixedIdentifiers(subject, resource, operation, prefix string) *Failure {
 15		if !validIdentifier(subject) {
 16			return invalidRequest(prefix+"subject", "field subject is not a parseable identifier")
 17		}
 18		if !validIdentifier(resource) {
 19			return invalidRequest(prefix+"resource", "field resource is not a parseable identifier")
 20		}
 21		if !validIdentifier(operation) {
 22			return invalidRequest(prefix+"operation", "field operation is not a parseable identifier")
 23		}
 24		return nil
 25	}
 26	
 27	// checkTriple reports the first unknown member of the triple in the published
 28	// order subject, resource, operation.
 29	func (s *Service) checkTriple(subject, resource, operation string) *Failure {
 30		return s.checkTripleWithFieldPrefix(subject, resource, operation, "")
 31	}
 32	
 33	func (s *Service) checkTripleWithFieldPrefix(subject, resource, operation, prefix string) *Failure {
 34		for _, check := range []struct {
 35			kind  store.CatalogKind
 36			id    string
 37			field string
 38		}{
 39			{store.CatalogSubject, subject, "subject"},
 40			{store.CatalogResource, resource, "resource"},
 41			{store.CatalogOperation, operation, "operation"},
 42		} {
